 function cancelRecording() { vadCleanup.current?.(); vadCleanup.current=null; recordGeneration.current++; recordAbort.current?.abort(); if(recordTimer.current)clearTimeout(recordTimer.current); if(recorderRef.current?.state==='recording')recorderRef.current.stop(); streamRef.current?.getTracks().forEach(t=>t.stop()); recorderRef.current=null; streamRef.current=null; }
