 async function recordMic() {
  if(recorderRef.current?.state==='recording'){recorderRef.current.stop();return;}
  if(micStarting.current||transcribing||!voiceConsent)return;
  if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){setError('Audio recording is unavailable here. Open in Chrome or dictate with Wispr into the answer field.');return;}
  micStarting.current=true;const generation=++recordGeneration.current;
  stopSpeech();setError('');
  try {
   const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
   if(generation!==recordGeneration.current){stream.getTracks().forEach(t=>t.stop());return;}
   streamRef.current=stream;
   const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));
   const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);recorderRef.current=recorder;const chunks:Blob[]=[];
   recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
   recorder.onerror=()=>{cancelRecording();setListening(false);setError('Microphone recording failed. Please try again.');};
   recorder.onstop=async()=>{
    vadCleanup.current?.();vadCleanup.current=null;if(recordTimer.current)clearTimeout(recordTimer.current);stream.getTracks().forEach(t=>t.stop());
    if(generation!==recordGeneration.current)return;
    recorderRef.current=null;streamRef.current=null;setListening(false);setTranscribing(true);
    try{
     const clip=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});if(clip.size<100)throw Error('No audio captured. Please speak and record again.');
     if(clip.size>4*1024*1024)throw Error('Recording is too large. Please use a shorter answer.');
     const controller=new AbortController();recordAbort.current=controller;const timeout=setTimeout(()=>controller.abort(),50000);
     let response:Response;try{response=await fetch('/api/transcribe',{method:'POST',headers:{'Content-Type':clip.type,'X-Audio-Consent':'yes','X-Interview-Language':active?.language||'en-IN'},body:clip,signal:controller.signal});}finally{clearTimeout(timeout);}
     const data=await response.json() as {transcript?:string;error?:string};if(!response.ok)throw Error(data.error||'Transcription failed.');
     if(generation!==recordGeneration.current)return;
     if(!data.transcript?.trim())throw Error('No clear speech was detected. Please record again.');
     setText(previous=>(previous+' '+data.transcript).trim().slice(0,6000));notify('Transcript ready. Review it, then send your answer.');
    }catch(e){if(generation===recordGeneration.current)setError(e instanceof Error&&e.name!=='AbortError'?e.message:'Transcription timed out. Please record again or type your answer.');}
    finally{if(generation===recordGeneration.current)setTranscribing(false);}
   };
   recorder.start();setListening(true);setVoiceState('waiting');
   if(autoStop && typeof AudioContext!=='undefined'){try{vadCleanup.current=monitorVoice(stream,pauseMs,setVoiceState,empty=>{if(generation!==recordGeneration.current)return;if(empty){cancelRecording();setListening(false);setError('No speech detected. Move closer to the microphone and try again.');}else if(recorder.state==='recording')recorder.stop();});}catch{notify('Automatic pause detection is unavailable. Press Stop when finished.');}}
   recordTimer.current=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},45000);
  }catch(e){streamRef.current?.getTracks().forEach(t=>t.stop());streamRef.current=null;setListening(false);setError(e instanceof Error&&e.name==='NotAllowedError'?'Microphone permission was denied. Allow microphone access in the browser, then try again.':'Could not start audio recording. Check the microphone and try again.');}
  finally{micStarting.current=false;}
 }
 function toggleMic() {
  if(providerState!=='ready'){setError('Voice connection is not ready. Retry the connection check above.');return;}
  if(configured){void recordMic();return;}
  if (listening) { recognition.current?.stop(); setListening(false); return; }
  stopSpeech();
  const Ctor = (window as unknown as { SpeechRecognition?: new () => Recognition; webkitSpeechRecognition?: new () => Recognition }).SpeechRecognition || (window as unknown as { webkitSpeechRecognition?: new () => Recognition }).webkitSpeechRecognition;
  if (!Ctor) { setError('Voice recognition is unavailable in this browser. Use the text box, or open in a browser that supports Web Speech recognition.'); return; }
  const rec = new Ctor(); rec.lang = speechLocale(active?.language || 'en-IN'); rec.continuous = false; rec.interimResults = false;
  rec.onresult = event => { const entry = event.results[event.resultIndex]; if (entry?.isFinal) setText(previous => `${previous} ${entry[0].transcript}`.trim()); };
  rec.onerror = event => { setListening(false); setError(event.error === 'not-allowed' ? 'Microphone permission was denied. Allow this site in browser microphone settings and check your input device.' : event.error === 'no-speech' ? 'The browser detected no speech. Check your selected microphone, click the mic again, and speak immediately. You can also dictate into the answer field with Wispr Flow.' : `Browser speech failed (${event.error}). Check your microphone and connection, or dictate with Wispr Flow.`); };
  rec.onend = () => setListening(false); recognition.current = rec;
  try { rec.start(); setListening(true); setError(''); } catch { setError('Could not start microphone. Try again or type your answer.'); }
 }
